 const bl=dc/nb,blocks=[];for(let i=0;i<nb;i++)blocks.push(cw.slice(i*bl,(i+1)*bl));const ecs=blocks.map(ecc);const all=[];
 for(let i=0;i<bl;i++)blocks.forEach(b=>all.push(b[i]));for(let i=0;i<ecn;i++)ecs.forEach(e=>all.push(e[i]));
 const M=[...Array(n)].map(()=>new Array(n).fill(null));const F=(r,c,val)=>{if(r>=0&&c>=0&&r<n&&c<n)M[r][c]=val};
