 M[n-8][8]=true;const res=[];for(let i=0;i<9;i++){res.push([8,i],[i,8])}for(let i=0;i<8;i++){res.push([8,n-1-i],[n-1-i,8])}res.forEach(([r,c])=>{if(M[r][c]===null)M[r][c]=false});
 const fn=M.map(r=>r.map(x=>x!==null));const ab=[];all.forEach(b=>{for(let i=7;i>=0;i--)ab.push((b>>i)&1)});
 let k=0;for(let c=n-1;c>0;c-=2){if(c===6)c--;for(let t=0;t<n;t++){const up=((n-1-c)>>1)%2===0;const r=up?n-1-t:t;for(let d=0;d<2;d++){const cc=c-d;if(!fn[r][cc]){M[r][cc]=k<ab.length?!!ab[k]:false;k++}}}}
 const MK=[(r,c)=>(r+c)%2===0,(r)=>r%2===0,(r,c)=>c%3===0,(r,c)=>(r+c)%3===0,(r,c)=>((r>>1)+((c/3)|0))%2===0,(r,c)=>(r*c)%2+(r*c)%3===0,(r,c)=>((r*c)%2+(r*c)%3)%2===0,(r,c)=>((r+c)%2+(r*c)%3)%2===0];
 const fmt=mk=>{let d=(0<<3|mk)<<10,x=d;for(let i=14;i>=10;i--)if(x>>i&1)x^=0x537<<(i-10);return((d|x)^0x5412)};
