function mod12Signals(r){const c=U(r.uid),j=(DB.jobs||[]).find(x=>x.id===r.job);const out=[];const age=c&&c.joined?Math.round((Date.now()-c.joined)/864e5):null;const n=(DB.reviews||[]).filter(x=>x.uid===r.uid).length;
 out.push([!!(j&&j.status==="completed"),j?"Job marked complete":"No job on file"]);out.push([!!(j&&j.custConfirmed),j&&j.custConfirmed?"Customer confirmed the job":"Customer never confirmed the job"]);
 const paid=j&&((j.escrow&&(j.escrow.ms||[]).some(x=>x.status==="released"))||(DB.quotes||[]).some(q=>q.job===j.id&&q.status==="accepted"));out.push([!!paid,paid?"Quote accepted / payment on record":"No accepted quote or payment"]);
 out.push([age==null||age>14,age==null?"Account age unknown":age+" day-old account"]);const wk=(DB.reviews||[]).filter(x=>x.uid===r.uid&&Math.abs(x.date-r.date)<7*864e5).length;out.push([wk<4,n+" review"+(n===1?"":"s")+" on Sawyer"+(wk>1?", "+wk+" within a week of this one":"")]);if(j&&r.date-(j.created||0)<864e5)out.push([false,"Reviewed less than a day after the job was posted"]);return out}
VIEWS.mod=(p,q)=>{const m=me();if(!m)return VIEWS.signup(null,{next:"/mod"});if(!v12Staff(m))return`<section class="page narrow">${empty("lock","Trust team only","This page is for Sawyer's moderators. If a review looks wrong, tap Report under it.","")}</section>`;q=q||{};const tab=q.t==="done"?"done":"open";
 const reps=(DB.reports12||[]);const disp=(DB.reviews||[]).filter(r=>r.dispute);const items=[];
 const byRev={};reps.forEach(x=>{(byRev[x.rid]=byRev[x.rid]||[]).push(x)});
 Object.entries(byRev).forEach(([rid,xs])=>{const r=(DB.reviews||[]).find(y=>y.id===rid)||(DB.rmrev12||[]).find(y=>y.id===rid);const open=xs.some(x=>x.status==="open"||x.status==="asked");items.push({kind:"report",id:(xs.find(x=>x.status==="open"||x.status==="asked")||xs[0]).id,r,xs,open,date:Math.max(...xs.map(x=>x.date)),asked:xs.some(x=>x.status==="asked")})});
 disp.forEach(r=>{if(byRev[r.id])return;const open=r.dispute.status==="open"||r.dispute.status==="asked";items.push({kind:"dispute",id:r.id,r,xs:[],open,date:r.dispute.date,asked:r.dispute.status==="asked"})});
 (DB.rmrev12||[]).forEach(r=>{if(!byRev[r.id]&&r.dispute)items.push({kind:"dispute",id:r.id,r,xs:[],open:false,date:r.removed.at})});
 const list=items.filter(x=>tab==="open"?x.open:!x.open).sort((a,b)=>tab==="open"?a.date-b.date:b.date-a.date);const nOpen=items.filter(x=>x.open).length;
 const card=x=>{const r=x.r;if(!r)return"";const pro=U(r.cid),c=U(r.uid),j=(DB.jobs||[]).find(y=>y.id===r.job);const removed=!(DB.reviews||[]).includes(r);const dec=x.kind==="dispute"?r.dispute&&r.dispute.dec||r.removed:(x.xs.find(y=>y.dec)||{}).dec;
  return`<article class="card mod12-i ${x.open?"":"done"}"><header class="mod12-h"><span class="badge ${x.kind==="report"?"b-urg":""}">${I(x.kind==="report"?"flag":"shield",12)}${x.kind==="report"?x.xs.length+" report"+(x.xs.length>1?"s":""):"Pro dispute"}</span>${x.asked?`<span class="badge">Waiting on reviewer</span>`:""}<span class="muted small">Opened ${ago(x.date)} · ${esc(v12Nm(pro))}</span></header>
  <div class="mod12-g"><div><blockquote class="mod12-q">${starStr(r.stars)}<p>${esc(r.text)}</p><footer class="small muted">${esc(nameOf(c))} · ${j?esc(j.archived||j.title==="Past job"?(j.sub||j.cat):j.title):"no job"} · ${fmtDate(r.date)}${removed?" · <b>removed</b>":""}</footer></blockquote>
   <ul class="mod12-why">${x.xs.map(y=>`<li>${I("flag",13)}<span><b>${esc(RP12[y.reason]||y.reason)}</b>${y.note?" · “"+esc(y.note)+"”":""} <small class="muted">by ${esc(nameOf(U(y.by)))}, ${ago(y.date)}</small></span></li>`).join("")}${r.dispute?`<li>${I("shield",13)}<span><b>Pro's dispute:</b> “${esc(r.dispute.reason)}”</span></li>`:""}</ul></div>
   <div><b class="small">Signals</b><ul class="mod12-s">${mod12Signals(r).map(([ok,t])=>`<li class="${ok?"ok":"bad"}">${I(ok?"check":"info",13)}${esc(t)}</li>`).join("")}</ul></div></div>
  ${x.open?`<form class="mod12-f" data-mod12="${x.kind}|${x.id}"><label class="sr-only" for="mn${x.id}">Decision note</label><input id="mn${x.id}" name="note" maxlength="400" placeholder="Note for the record (shared with the people involved)"><div class="row"><button type="button" class="btn sm ghost" data-md="ask">Ask reviewer for proof</button><button type="button" class="btn sm" data-md="keep">${I("check",14)}Keep review</button><button type="button" class="btn sm danger12" data-md="remove">${I("x",14)}Remove review</button></div></form>`:dec?`<p class="small mod12-dec">${I(dec.what==="remove"?"x":"check",13)}<b>${dec.what==="remove"?"Removed":"Kept"}</b> by ${esc(nameOf(U(dec.by)))} ${ago(dec.at)}: ${esc(dec.note)}</p>`:""}</article>`};
 return`<section class="mod12"><div class="b12-top"><div class="wrap"><span class="eyebrow">${I("shield",14)}Trust &amp; safety</span><h1>Review moderation</h1><p class="muted">Reports from users and disputes from pros. Every decision is logged and the people involved are told why.</p>
  <nav class="h12-tabs" aria-label="Queue"><a href="${href("mod")}" class="${tab==="open"?"on":""}" ${tab==="open"?'aria-current="page"':""}>${I("flag",15)}<span>Open (${nOpen})</span></a><a href="${href("mod",null,{t:"done"})}" class="${tab==="done"?"on":""}" ${tab==="done"?'aria-current="page"':""}>${I("check",15)}<span>Decided (${items.length-nOpen})</span></a></nav></div></div>
  <div class="wrap mod12-body">${list.map(card).join("")||empty("check",tab==="open"?"Queue is clear":"Nothing decided yet",tab==="open"?"New reports and disputes show up here.":"","")}</div></section>`};

